@Service
class PaymentClient {
    @CircuitBreaker(name = "payments", fallbackMethod = "cachedReceipt")
    Receipt authorize(Order order) {
        return api.authorize(order);              // proxied: breaker + fallback apply
    }

    Receipt cachedReceipt(Order order, RuntimeException e) {   // must be fast and safe
        return receipts.findCached(order.id()).orElseThrow(() -> e);
    }
}
